import importlib.util,json,pathlib,subprocess,sys
root=pathlib.Path(sys.argv[1]); out=pathlib.Path(sys.argv[2]); sys.path[:0]=[str(root/'src'),str(root/'tests')]
spec=importlib.util.spec_from_file_location('bench',root/'tools/bench_b0.py');b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b);t=b.torch;t.set_num_threads(1)
pools=[(f'grid{k}',b.full_factorial([3]*k).double()-1) for k in (2,3,4)]
pools.append(('random500',2*t.rand(500,3,dtype=t.float64,generator=t.Generator().manual_seed(0))-1)); rows=[]
for name,C in pools:
 F=b.polynomial_features(C,degree=2);p=F.shape[1]
 for n in [p,2*p]+([7] if name=='grid2' else []):
  for criterion in 'DAI':
   for seed in range(5):
    row=dict(pool=name,n=n,criterion=criterion,seed=seed)
    try:
     r=b.optimal_design(F,n,criterion=criterion,restarts=1,generator=t.Generator().manual_seed(seed))
     row.update(ids=r['ids'].tolist(),objective=r['objective'],efficiency_lower_bound=r['efficiency_lower_bound'])
     if criterion=='D':row['d_efficiency_lower_bound']=r['d_efficiency_lower_bound']
    except ValueError as exc:row['error']=type(exc).__name__+': '+str(exc)
    rows.append(row)
out.write_text(json.dumps(rows,allow_nan=False)+'\n');print(out.name,len(rows),'rows',flush=True)

